    public static class MariaKonopnicka
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Ale jak na ten słup położone będą tylko pieniądze, a nie będzie ani honoru, ani sławności, ani mądrości, to po co ludzie będą na ten słup liźć? Jak pan dobrodziej myśli? Po pieniądze uni będą liźć i po nic więcej?", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "On i to nawet wie może, ile wróbli gnieździ się w gzymsach starego browaru, który panuje nad uliczką wysokim, poczerniałym kominem – w gałęziach chorowitej, rosnącej przy nim topoli, która nie ma ani siły do życia, ani ochoty do śmierci…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "A gdy serce twe przytłoczy myśl, że żyć nie warto, z łez ocieraj cudze oczy, chociaż twoich nie otarto", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "A ja wam mówię, że Bóg też ma noce Bezsenne…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Ach, śpiesz się dziewczyno, nie splataj warkoczy, Do strugi, za wioskę bież strzałą; Nim ptaszka w niej skrzydła czarniawe umoczy, Ty w wodzie twarzyczkę myj białą.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Albo mi ptaszkowie Swoje skrzydła dajcie, Albo mi przed chatą Nocką nie śpiewajcie!…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Choćbyś poznał ziemię całą Milion gwiazd jeszcze zostało! Choćbyś gwiazdy znał na niebie, Jeszcze musisz znać… sam siebie.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Cóż to jest pieśń? dźwięk słów pusty, jako wiatru szelest, Poezya najpiękniejsza jeszcze prawdą nie jest", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Czy to bajka, czy nie bajka, Myślcie sobie, jak tam chcecie, A ja przecież wam powiadam: Krasnoludki są na świecie.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Duch mój, ptak boży, co go Pan w czas ranny, I w czas wiosenny wypuścił pod niebem, A z rąk mu daje przeczystych ros manny, I karmi chlebem.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Dym ten wszakże nie przybierał już teraz dawnych rozlicznych kształtów, tylko zawsze zamienił się w mglistą postać jej drogiego chłopca. Zrywała się wtedy ze stołka i wyciągała drżące, wyschłe ręce. Ale mglistą postać wiatr unosił i rozwiewał ją gdzieś w błękitach…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Ej, ty praco, twarda praco, Zmyślili cię, nie wiem, na co.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Ej wy góry, sine góry, Zaklęte dokoła! Myśl orlemi leci pióry Na wasze przyczoła…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "I miasto i wioska To jeden nasz świat! I wszędzie, dziecino, Twa siostra, twój brat!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "...Iskrę słońca masz w sobie, Nie zdmuchnioną i w grobie: Czemu ziębniesz wśród cienia? Czemu błąkasz się w nocy? Roztlij ją, jak pochodnię, Na twe drogi przewodnie!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Jadą, jadą dzieci drogą… Siostrzyczka i brat I nadziwić się nie mogą, Jaki piękny świat!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Jaskółeczka do nas wraca Z oddalonej drogi. Śpiewem wita wioskę miłą, Miłej chaty progi.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Każde szczęście jest pragnieniem nieszczęścia.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Na granicie Wawel – na piasku Warszawa", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Nasza czarna jaskółeczka przyleciała do gniazdeczka przez daleki kraj! Bo w tym gniazdku się rodziła bo tu jest jej strzecha miła, bo tu jest jej raj!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Nie będzie Polak, z ojczyzny wyjęty, Luzem rzucony pomiędzy narody, Ale zbuduje Dom własny i święty, Dom przypodoban do starej zagrody. Już założone serc są fundamenty, Węgielny kamień jedności i zgody Pod gmach ojczystej wiary, uczuć, mowy, Pod Nową Polskę i pod żywot nowy.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Nie kocham jeszcze, a już mi jest drogi; Nie kocham jeszcze, a już drżę i płonę I duszę pełną o niego mam trwogi I myśli moje już tam, w jego progi Lecą stęsknione…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Nie rzucim ziemi, skąd nasz ród, Nie damy pogrześć mowy! Polski my naród, polski lud, Królewski szczep piastowy, Nie damy, by nas zniemczył wróg… – Tak nam dopomóż Bóg!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "O większego trudno zucha Jak był Stefek Burczymucha.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Piosenki, piosenki, Skąd wy się bierzecie? Czy tak wyrastacie Jako polne kwiecie?", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Proście wy Boga o takie mogiły, Które łez nie chcą, ni skarg, ni żałości, Lecz dają sercom moc czynu, zdrój siły, I żar miłości.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Szanuj, drogie dziecię moje, W małym ziarnku – przyszłe plony, W małej kropli – przyszłe zdroje, W szelągu – miliony. W każdej myśli – zaród czynu, Życie – w chwilce co ucieka, A sam w sobie – szanuj, synu, Przyszłego człowieka!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Tatrzańskie stoki w ziołach toną I noszą odzież rozkwieconą, Na mchu stawiają stopy bose I traw oddechem piją rosę…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Toś ty mleko piła z miski? A psik, kiciu, idź na myszki!", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Tylko miłość jest siłą, co złagodzić może ból świata.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Warszawo, Warszawo, ty czerwienny grodzie! Obrano cię niegdyś królową w narodzie. Nie obrano ciebie dla twojej urody, Jeno dla tej Wisły, dla tej Białej wody… Jeno dla tej starej mazowieckiej ziemi, Co cię kołysała szumami leśnemi…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "W szerokiem pustem polu, Na uroszonej ziemi, Tam dusza moja klęczy, Z skrzydłami złożonemi…", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Za ostatnim poetą zamknęła się brama.", Author = "Maria Konopnicka" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Maria_Konopnicka", Text = "Życie — jak woda. Kto z cichego zdroju Drobną czareczką nabiera napoju, Temu ust żary słodki gasi trunek, Jako błękitów pełen pocałunek.", Author = "Maria Konopnicka" },
        };
    }
}